from pathlib import Path
import base64, gzip, subprocess

PATCH = """"""
patch_bytes = gzip.decompress(base64.b64decode(PATCH))
patch_path = Path("phase14_5_14_quantitative_quality/phase14_5_14.patch")
patch_path.write_bytes(patch_bytes)
subprocess.run(["patch", "-p0", "--forward", "--batch", "-i", str(patch_path)], check=True)
print("Phase 14.5.14 quantitative quality patch applied")
